mapper.select:
/* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.selectAnnouncementList */ /* 공고 목록 조회 */
SELECT cap.ann_no AS annNo /** 공고번호 */ , cap.board_no AS boardNo /** 게시판번호 */ , cbi.board_nm AS boardNm /** 게시판명 */ , cbi.board_ty_cd AS boardTyCd /** 게시판유형코드 */ , cbi.apt_cmplex_no AS aptCmplexNo /** 아파트단지번호 */ , ac.apt_cmplex_nm AS aptCmplexNm /** 아파트단지명 */ , cap.ttl AS ttl /** 제목 */ , cap.cn AS cn /** 내용 */ , cap.wrtr_id AS wrtrId /** 작성자아이디 */ , cap.top_fix_yn AS topFixYn /** 상단고정여부 */ , TO_CHAR(cap.pblanc_bgng_dt, 'YYYY-MM-DD') AS pblancBgngDt /** 공고게시시작일 */ , TO_CHAR(cap.pblanc_end_dt, 'YYYY-MM-DD') AS pblancEndDt /** 공고게시종료일 */ , TO_CHAR(cap.rcrt_bgng_dt, 'YYYY-MM-DD') AS rcrtBgngDt /** 모집시작일 */ , TO_CHAR(cap.rcrt_end_dt, 'YYYY-MM-DD') AS rcrtEndDt /** 모집종료일 */ , TO_CHAR(cap.reg_dttm, 'YYYY-MM-DD') AS regDttm /** 등록일시 */ , TO_CHAR(cap.mdf_dttm, 'YYYY-MM-DD') AS mdfDttm /** 수정일시 */ , NVL(cap.inq_cnt, 0) AS inqCnt /** 조회수 */ , NVL(cap.del_yn, 'N') AS delYn /** 삭제여부 */ , NVL(cap.opn_yn, 'Y') AS opnYn /** 공개여부 */ , cap.atch_file_id AS atchFileId /** 첨부파일ID */ , NVL(( SELECT SUM(NVL(au.unit_cnt, 0)) FROM apt_unit au WHERE au.apt_cmplex_no = cbi.apt_cmplex_no ), NVL(ac.unit_cnt, 0)) AS unitCnt /** 공급세대수 */ , ( SELECT LISTAGG(af.file_og_name, ', ') WITHIN GROUP (ORDER BY af.file_sort_order, af.file_og_name) FROM attach_file af WHERE TO_CHAR(af.file_group_no) = cap.atch_file_id ) AS sbmsnDocNm /** 제출서류명 */ , CASE WHEN cap.rcrt_bgng_dt IS NULL OR cap.rcrt_end_dt IS NULL THEN '-' WHEN TRUNC(SYSDATE) < TRUNC(cap.rcrt_bgng_dt) THEN '예정' WHEN TRUNC(SYSDATE) > TRUNC(cap.rcrt_end_dt) THEN '마감' ELSE '진행중' END AS statusNm /** 공고상태 */ FROM center_ann_board_post cap INNER JOIN center_board_instance cbi ON cap.board_no = cbi.board_no LEFT JOIN apt_complex ac ON cbi.apt_cmplex_no = ac.apt_cmplex_no WHERE 1 = 1 AND NVL(cap.del_yn, 'N') = 'N'
AND LOWER(cap.ttl) LIKE '%' || LOWER(#{searchTtl}) || '%'
AND cbi.apt_cmplex_no = #{searchAptCmplexNo}
AND cap.rcrt_bgng_dt >= TO_DATE(#{searchFrom}, 'YYYY-MM-DD')
AND cap.rcrt_end_dt <= TO_DATE(#{searchTo}, 'YYYY-MM-DD')
AND CASE WHEN cap.rcrt_bgng_dt IS NULL OR cap.rcrt_end_dt IS NULL THEN '-' WHEN TRUNC(SYSDATE) < TRUNC(cap.rcrt_bgng_dt) THEN '예정' WHEN TRUNC(SYSDATE) > TRUNC(cap.rcrt_end_dt) THEN '마감' ELSE '진행중' END = #{searchStatus}
ORDER BY cap.reg_dttm DESC

mapper.insert:
SELECT 'ANN' || LPAD( NVL(MAX(TO_NUMBER(REGEXP_REPLACE(ann_no, '[^0-9]', ''))), 0) + 1 , 12, '0') FROM center_ann_board_post
/* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.insertAnnouncement */ /* 공고 등록 */
INSERT INTO center_ann_board_post ( ann_no /** 공고번호 */ , board_no /** 게시판번호 */ , ttl /** 제목 */ , cn /** 내용 */ , wrtr_id /** 작성자아이디 */ , top_fix_yn /** 상단고정여부 */ , pblanc_bgng_dt /** 공고게시시작일 */ , pblanc_end_dt /** 공고게시종료일 */ , rcrt_bgng_dt /** 모집시작일 */ , rcrt_end_dt /** 모집종료일 */ , reg_dttm /** 등록일시 */ , inq_cnt /** 조회수 */ , atch_file_id /** 첨부파일ID */ , del_yn /** 삭제여부 */ , opn_yn /** 공개여부 */ ) VALUES ( #{annNo} , ( SELECT board_no FROM ( SELECT cbi.board_no FROM center_board_instance cbi WHERE cbi.apt_cmplex_no = #{aptCmplexNo} AND NVL(cbi.use_yn, 'Y') = 'Y' AND ( cbi.board_ty_cd = 'ANN' OR cbi.board_nm LIKE '%공고%' ) ORDER BY cbi.board_no ) WHERE ROWNUM = 1 ) , #{ttl} , #{cn} , #{wrtrId} , NVL(#{topFixYn}, 'N') , TO_DATE(#{pblancBgngDt}, 'YYYY-MM-DD') , TO_DATE(#{pblancEndDt}, 'YYYY-MM-DD') , TO_DATE(#{rcrtBgngDt}, 'YYYY-MM-DD') , TO_DATE(#{rcrtEndDt}, 'YYYY-MM-DD') , SYSDATE , 0 , #{atchFileId} , NVL(#{delYn}, 'N') , NVL(#{opnYn}, 'Y') )

mapper.update:
        /* kr.or.ddit.domain.central.admin.mapper.AnnouncementMapper.deleteAnnouncement */
        /* 공고 삭제 처리 */

        UPDATE center_ann_board_post
        SET
        del_yn = 'Y'       /** 삭제여부 */
        , mdf_dttm = SYSDATE /** 수정일시 */
        WHERE ann_no = #{annNo}
